export const BrandLogo: React.FC<BrandLogoProps> = ({
  variant = 'full-white',
  className = '',
  height = 42,
  color,
  style = {}
}) => {
  const isChampagne = variant === 'full-champagne' || variant === 'monogram-champagne';
  const rawId = React.useId();
  const gradientId = `brandChampagneGradient-${rawId.replace(/[^a-zA-Z0-9_-]/g, '')}`;
  const heightStyle = typeof height === 'number' ? `${height}px` : height;

  // Determine fill color based on variant (color prop overrides any variant preset)
  let fillColor = '#FFFFFF';
  if (color) {
    fillColor = color;
  } else if (isChampagne) {
    fillColor = `url(#${gradientId})`;
  } else if (variant === 'full-burgundy' || variant === 'monogram-burgundy' || variant === 'house-burgundy') {
    fillColor = '#660E1A';
  } else if (variant === 'full-orange' || variant === 'monogram-orange') {
    fillColor = '#FA2F0E';
  } else if (variant === 'full-current' || variant === 'monogram-current' || variant === 'house-current') {
    fillColor = 'currentColor';
  }

  // Monogram / Favicon mark (Aspect ratio: 520.74 x 371.96)
  if (
    variant === 'monogram-white' ||
    variant === 'monogram-burgundy' ||
    variant === 'monogram-orange' ||
    variant === 'monogram-champagne' ||
    variant === 'monogram-current' ||
    variant === 'icon'
  ) {
    return (
      <svg
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 520.74 371.96"
        style={{
          height: heightStyle,
          width: 'auto',
          display: 'inline-block',
          verticalAlign: 'middle',
          flexShrink: 0,
          ...style
        }}
        className={`brand-monogram ${className}`}
        preserveAspectRatio="xMidYMid meet"
        aria-label="New Era Monogram"
      >
        {isChampagne && (
          <defs>
            <linearGradient id={gradientId} x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stopColor="#EFE1CE" />
              <stop offset="35%" stopColor="#DEC0A1" />
              <stop offset="70%" stopColor="#C8A580" />
              <stop offset="100%" stopColor="#E2CFB8" />
            </linearGradient>
          </defs>
        )}
        <path fill={fillColor} fillRule="nonzero" d={MONOGRAM_PATH} />
      </svg>
    );
  }

  // House roofline only
  if (variant === 'house-burgundy' || variant === 'house-white' || variant === 'house-current') {
    return (
      <svg
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 1062.73 501.78"
        style={{
          height: heightStyle,
          width: 'auto',
          display: 'inline-block',
          verticalAlign: 'middle',
          flexShrink: 0,
          ...style
        }}
        className={`brand-house ${className}`}
        preserveAspectRatio="xMidYMid meet"
        aria-label="New Era House Mark"
      >
        <path fill={fillColor} fillRule="evenodd" d={LOGO_FRAME_HOUSE_PATH} />
      </svg>
    );
  }

  // Full official logo with Twin Gables House, NEW ERA typographic mark & REAL ESTATE subtext
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 1062.73 501.78"
      style={{
        height: heightStyle,
        width: 'auto',
        display: 'inline-block',
        verticalAlign: 'middle',
        flexShrink: 0,
        ...style
      }}
      className={`brand-logo-svg ${className}`}
      preserveAspectRatio="xMidYMid meet"
      aria-label="New Era Real Estate"
    >
      <defs>
        {isChampagne && (
          <linearGradient id={gradientId} x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#EFE1CE" />
            <stop offset="35%" stopColor="#DEC0A1" />
            <stop offset="70%" stopColor="#C8A580" />
            <stop offset="100%" stopColor="#E2CFB8" />
          </linearGradient>
        )}
      </defs>
      <g>
        <path fill={fillColor} fillRule="evenodd" d={LOGO_FRAME_HOUSE_PATH} />
        <path fill={fillColor} fillRule="nonzero" d={LOGO_NEW_ERA_PATH} />
        <path fill={fillColor} fillRule="nonzero" d={LOGO_REAL_ESTATE_PATH} />
      </g>
    </svg>
  );
};
